/*
 * A174006  Array T(n, k) = k^(n-1) + (k-1)*cos(n*Pi/2), read by
 *          antidiagonals.
 * https://oeis.org/A174006
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the n-th term of the sequence generated by reading the
 *            infinite array T(n,k) = k^(n-1) + (k-1)*cos(n*Pi/2) by
 *            anti‑diagonals. For n ≥ 2, a(n) is the (n‑2)-th element of the
 *            resulting triangular array, where each row r contains r elements
 * Range:     u8 n <= 24, u16 n <= 58, u32 n <= 157, u64 n <= 412,
 *            u128 n <= 1092, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <limits.h>

seq_t a(idx_t n) {
    /* offset 2 in OEIS means a(2) is the first element. */
    idx_t m = n - 2;                /* zero‑based position in the flattened array */

    /* Find the row r such that r*(r+1)/2 > m.  Use binary search to avoid
       loss of precision for very large n. */
    idx_t low = 1, high = 1;
    while ( ((unsigned __int128)high * (high + 1) / 2) <= m ) {
        high <<= 1;                 /* double until upper bound large enough */
        if (high == 0) {            /* overflow protection */
            high = UINT64_MAX;
            break;
        }
    }
    while (low < high) {
        idx_t mid = low + ((high - low) >> 1);
        unsigned __int128 val = (unsigned __int128)mid * (mid + 1) / 2;
        if (val > m)
            high = mid;
        else
            low = mid + 1;
    }
    idx_t r = low;                         /* row number (1‑based) */

    /* position within the row (0‑based) */
    unsigned __int128 prev_total = (unsigned __int128)(r - 1) * r / 2;
    idx_t j = m - (idx_t)prev_total;        /* offset within row r */

    /* The n‑parameter of T is r – j.  The k‑parameter depends on that. */
    idx_t n_val = r - j;
    seq_t k_val = (n_val >= 3) ? (seq_t)(j + 2) : (seq_t)1;

    /* Compute k_val^(n_val-1) by fast exponentiation. */
    seq_t pow_val = 1;
    idx_t exp = n_val - 1;
    seq_t base = k_val;
    while (exp) {
        if (exp & 1) pow_val *= base;
        base *= base;
        exp >>= 1;
    }

    /* Add or subtract (k_val-1) depending on the parity of n_val/2. */
    if (n_val & 1) {                /* n_val is odd, cos term = 0 */
        return pow_val;
    } else {                       /* n_val is even, cos term = (-1)^(n_val/2) */
        idx_t half = n_val >> 1;    /* n_val / 2 */
        if ((half & 1) == 0) {     /* even half -> cos = +1 */
            return pow_val + (k_val - 1);
        } else {                   /* odd half -> cos = -1 */
            return pow_val - (k_val - 1);
        }
    }
}
